// GENERATED by scripts/sync-shared.mjs from src/. Do not edit: change src/ and run `npm run sync:shared`.
// Crowd scoring. The same rules are implemented in SQL (score_tier in the
// migrations); tests/unit/sql.test.ts checks the two agree.

export type TierId = 'obvious' | 'clever' | 'fair' | 'rare' | 'outlier' | 'lone' | 'none';

export interface TierInfo {
  id: TierId;
  name: string;
  points: number;
  /** Symbol used in the share text. */
  symbol: string;
  /** One-line rule for the mark scheme. */
  rule: string;
}

export const TIERS: Record<TierId, TierInfo> = {
  obvious: { id: 'obvious', name: 'Obvious', points: 10, symbol: '·', rule: '1 in 5 or more said it' },
  clever: { id: 'clever', name: 'Predictably Clever', points: 15, symbol: '○', rule: 'famous number' },
  fair: { id: 'fair', name: 'Fair', points: 30, symbol: '◐', rule: '4% to 20% said it' },
  rare: { id: 'rare', name: 'Rare', points: 60, symbol: '●', rule: '1 in 200 to 4% said it' },
  outlier: { id: 'outlier', name: 'Outlier', points: 85, symbol: '★', rule: 'fewer than 1 in 200 said it' },
  lone: { id: 'lone', name: 'Lone Wolf', points: 100, symbol: '✦', rule: 'nobody else said it' },
  none: { id: 'none', name: 'No answer', points: 0, symbol: '✗', rule: 'out of time' },
};

/** Mark-scheme order, lowest to highest. */
export const TIER_ORDER: readonly TierId[] = ['obvious', 'clever', 'fair', 'rare', 'outlier', 'lone'];

export const MAX_TOTAL = 700;
/** All of a day's ghosts together count as this many players… */
export const GHOST_CROWD = 100;
/** …fading to nothing by this many real players. */
export const GHOST_FADE_PLAYERS = 500;

/**
 * The weight of one ghost: (100 ÷ ghostCount) × max(0, 1 − realPlayers ÷ 500).
 * ghostCount includes ghosts who ran out of time.
 */
export function ghostWeight(realPlayers: number, ghostCount: number): number {
  if (ghostCount <= 0) return 0;
  return (GHOST_CROWD / ghostCount) * Math.max(0, 1 - realPlayers / GHOST_FADE_PLAYERS);
}

export interface CrowdCounts {
  /** Real answers to this prompt equal to yours, including your own. */
  sameReal: number;
  /** All real answers to this prompt, including your own. */
  totalReal: number;
  /** Ghost answers equal to yours. */
  sameGhost: number;
  /** Ghosts who answered this prompt (not those who ran out of time). */
  totalGhost: number;
  /** Every ghost for this prompt, including those who ran out of time. */
  ghostCount: number;
  /** Distinct real players today. */
  realPlayers: number;
  /** Is the answer on this prompt's "famous numbers" list? */
  clever: boolean;
}

export interface Score {
  tier: TierId;
  points: number;
  /** Weighted share of answers equal to yours, 0 to 1. */
  share: number;
}

/**
 * Tier thresholds, set with scripts/simulate-tiers.ts. Outlier and Rare are judged
 * on the share of OTHER players' answers (yours left out), so a crowd of about a
 * hundred can still produce an Outlier: fewer than 1 in 200 others said it.
 * Lone Wolf means nobody else at all: no other real player and no ghost.
 */
export const OBVIOUS_SHARE = 0.2;
export const OUTLIER_OTHERS = 0.005;
export const FAIR_OTHERS = 0.04;

export function scoreAnswer(c: CrowdCounts): Score {
  const w = ghostWeight(c.realPlayers, c.ghostCount);
  const same = c.sameReal + w * c.sameGhost;
  const total = c.totalReal + w * c.totalGhost;
  const share = total > 0 ? same / total : 1;
  // Everyone else: take away the answer being scored (a real player's, or a ghost's own weight).
  const self = c.sameReal >= 1 ? 1 : w;
  const others = total > 0 ? Math.max(0, same - self) / total : 0;

  let tier: TierId;
  if (c.sameReal <= 1 && w * c.sameGhost === 0) tier = 'lone';
  else if (share >= OBVIOUS_SHARE) tier = 'obvious';
  else if (others < OUTLIER_OTHERS) tier = 'outlier';
  else if (c.clever) tier = 'clever';
  else if (others >= FAIR_OTHERS) tier = 'fair';
  else tier = 'rare';

  return { tier, points: TIERS[tier].points, share };
}

/** "4%", "under 1%", "23%" */
export function formatShare(share: number): string {
  const pct = share * 100;
  if (pct > 0 && pct < 1) return 'under 1%';
  return `${Math.round(pct)}%`;
}
